"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["95107"],{51848(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_valor_dominio.ordem_com_codigo_repetido","status":422,"titulo":"A ordem repete um valor"},"descricao":{"codigo":"uniplus.configuracao.fato_valor_dominio.ordem_com_codigo_repetido","requisitos":["UNI-REQ-0159"],"oQueAconteceu":["O administrador enviou a nova ordem dos valores de um fato (`PUT /api/configuracao/admin/fatos-candidato/{id}/ordem-dos-valores`) com o mesmo c\xf3digo mais de uma vez. Cada valor ocupa uma \xfanica posi\xe7\xe3o na ordem, ent\xe3o a lista n\xe3o pode repeti-lo. A corre\xe7\xe3o da ordem das op\xe7\xf5es de um fato \xe9 regra do UNI-REQ-0159; a lista completa e sem repeti\xe7\xe3o \xe9 a forma que a API exige para aplic\xe1-la de uma vez.","A recusa vem na lista `errors` da resposta, com `field` igual a `codigos`, e a mensagem diz o que corrigir. A ordem dos valores do fato n\xe3o \xe9 alterada. Se a lista tiver mais de um problema, cada um vem numa entrada pr\xf3pria da mesma resposta. Os espa\xe7os nas pontas de cada c\xf3digo s\xe3o desconsiderados, mas mai\xfasculas e min\xfasculas contam: `eja` n\xe3o \xe9 o mesmo valor que `EJA`."],"comoResolver":["Deixe cada c\xf3digo uma \xfanica vez, na posi\xe7\xe3o em que o valor deve aparecer, e envie a lista de novo. A mensagem n\xe3o repete os c\xf3digos enviados. A lista continua precisando trazer todos os valores do fato, ativos e desativados, e s\xf3 c\xf3digos do fato."],"ondeAparece":["Reordena\xe7\xe3o dos valores de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato valor dominio"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);